#include <stdio.h>

void bubbleSort(int a[], int n) {
    for (int i = 0; i < n - 1; i++) {          /* মোট n-1 pass */
        int swapped = 0;
        for (int j = 0; j < n - i - 1; j++) {  /* ডানের i টি ঘর sorted */
            if (a[j] > a[j + 1]) {             /* পাশাপাশি দুটি তুলনা */
                int t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
                swapped = 1;
            }
        }
        if (!swapped) break;                   /* swap হয়নি → sorted */
    }
}

int main(void) {
    int a[] = {45, 12, 78, 34, 23};
    int n = sizeof(a) / sizeof(a[0]);
    bubbleSort(a, n);
    for (int i = 0; i < n; i++)
        printf("%d ", a[i]);                   /* 12 23 34 45 78 */
    return 0;
}
